// Character classification helpers for the YAML scanner/emitter.
//
// IMPORTANT: this project must not use regular expressions anywhere, so every
// classification below is expressed as an explicit code-point comparison.
//
// The reader yields '\0' for "past end of stream" (the same sentinel PyYAML's
// Reader.peek() uses), so most helpers treat '\0' as a terminator.

export const NUL = '�';

/** Single decimal digit 0-9. */
export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

/** Numeric value of a decimal digit. */
export function digitValue(ch) {
  return ch.charCodeAt(0) - 48;
}

/** Hexadecimal digit. */
export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

/** Numeric value of a hexadecimal digit. */
export function hexValue(ch) {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (ch >= 'a' && ch <= 'f') return ch.charCodeAt(0) - 87;
  return ch.charCodeAt(0) - 55;
}

/** ASCII letter. */
export function isAlpha(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

/** Characters allowed in anchor names / the non-URI part of tag handles. */
export function isAlphaNumericDashUnderscore(ch) {
  return isAlpha(ch) || isDigit(ch) || ch === '-' || ch === '_';
}

/** The five YAML line breaks (U+000A, U+000D, U+0085, U+2028, U+2029). */
export function isLineBreak(ch) {
  return ch === '\n' || ch === '\r' || ch === '' || ch === ' ' || ch === ' ';
}

/** Line break or end of stream. */
export function isLineBreakOrNul(ch) {
  return ch === NUL || isLineBreak(ch);
}

export function isSpaceOrTab(ch) {
  return ch === ' ' || ch === '\t';
}

/** Space, tab, line break or end of stream: "whitespace" in PyYAML's scanner. */
export function isWhitespaceOrEnd(ch) {
  return ch === NUL || ch === ' ' || ch === '\t' || isLineBreak(ch);
}

/** Flow collection indicators. */
export function isFlowIndicator(ch) {
  return ch === ',' || ch === '[' || ch === ']' || ch === '{' || ch === '}';
}

/**
 * YAML 1.1 printable characters, as enforced by PyYAML's Reader.
 * Everything outside this set makes the loader raise a ReaderError.
 */
export function isPrintableCodePoint(cp) {
  if (cp === 0x09 || cp === 0x0a || cp === 0x0d || cp === 0x85) return true;
  if (cp >= 0x20 && cp <= 0x7e) return true;
  if (cp >= 0xa0 && cp <= 0xd7ff) return true;
  if (cp >= 0xe000 && cp <= 0xfffd) return true;
  if (cp >= 0x10000 && cp <= 0x10ffff) return true;
  return false;
}

/**
 * Characters the emitter can leave unescaped inside a double-quoted scalar when
 * allow_unicode is false: printable ASCII plus tab handled separately.
 */
export function isAsciiPrintableCodePoint(cp) {
  return cp >= 0x20 && cp <= 0x7e;
}

/** True when the emitter considers the code point printable at all. */
export function isEmitterPrintableCodePoint(cp) {
  return isPrintableCodePoint(cp) && cp !== 0xfeff;
}

