// Source positions and the error hierarchy, mirroring PyYAML's error classes so
// that diagnostics come out with byte-identical wording.

/** A position inside the input buffer (all offsets are in code points). */
export class Mark {
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer; // array of code-point strings, or null
    this.pointer = pointer;
  }

  /** The offending line plus a caret, exactly like PyYAML's Mark.get_snippet. */
  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    const isBreak = (ch) =>
      ch === '�' || ch === '\r' || ch === '\n' || ch === '' || ch === ' ' || ch === ' ';
    let head = '';
    let start = this.pointer;
    while (start > 0 && !isBreak(this.buffer[start - 1])) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && !isBreak(this.buffer[end])) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = this.buffer.slice(start, end).join('');
    return (
      ' '.repeat(indent) + head + snippet + tail + '\n' +
      ' '.repeat(indent + this.pointer - start + head.length) + '^'
    );
  }

  toString() {
    const snippet = this.getSnippet();
    let where = '  in "' + this.name + '", line ' + (this.line + 1) + ', column ' + (this.column + 1);
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

/** Base class; `pyName` is the dotted name Python prints in a traceback. */
export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.name = 'YAMLError';
    this.pyName = 'yaml.error.YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super('');
    this.context = context ?? null;
    this.contextMark = contextMark ?? null;
    this.problem = problem ?? null;
    this.problemMark = problemMark ?? null;
    this.note = note ?? null;
    this.name = 'MarkedYAMLError';
    this.pyName = 'yaml.error.MarkedYAMLError';
    this.message = this.describe();
  }

  describe() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (
      this.contextMark !== null &&
      (this.problem === null ||
        this.problemMark === null ||
        this.contextMark.name !== this.problemMark.name ||
        this.contextMark.line !== this.problemMark.line ||
        this.contextMark.column !== this.problemMark.column)
    ) {
      lines.push(String(this.contextMark));
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(String(this.problemMark));
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }

  toString() {
    return this.describe();
  }
}

export class ReaderError extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.nameField = name;
    this.position = position;
    this.character = character; // code point number
    this.encoding = encoding;
    this.reason = reason;
    this.name = 'ReaderError';
    this.pyName = 'yaml.reader.ReaderError';
    this.message = this.describe();
  }

  describe() {
    const hex = this.character.toString(16).padStart(4, '0');
    return (
      'unacceptable character #x' + hex + ': ' + this.reason + '\n' +
      '  in "' + this.nameField + '", position ' + this.position
    );
  }

  toString() {
    return this.describe();
  }
}

function marked(className, pyModule) {
  return class extends MarkedYAMLError {
    constructor(context, contextMark, problem, problemMark, note) {
      super(context, contextMark, problem, problemMark, note);
      this.name = className;
      this.pyName = 'yaml.' + pyModule + '.' + className;
      this.message = this.describe();
    }
  };
}

export const ScannerError = marked('ScannerError', 'scanner');
export const ParserError = marked('ParserError', 'parser');
export const ComposerError = marked('ComposerError', 'composer');
export const ConstructorError = marked('ConstructorError', 'constructor');

export class EmitterError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'EmitterError';
    this.pyName = 'yaml.emitter.EmitterError';
  }
}

export class SerializerError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'SerializerError';
    this.pyName = 'yaml.serializer.SerializerError';
  }
}

export class RepresenterError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'RepresenterError';
    this.pyName = 'yaml.representer.RepresenterError';
  }
}

/** Stand-ins for the Python built-in exceptions we can surface. */
export class PyTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TypeError';
    this.pyName = 'TypeError';
  }
}

export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
    this.pyName = 'ValueError';
  }
}

