// Guard rails for the generated code in /output:
//   - every source byte must be printable ASCII (plus tab/newline), so that no
//     invisible control character can sneak into a string literal
//   - no regular expressions, no JSON interfaces, no CommonJS, no bare imports
// Usage: node /workspace/dev/lint.mjs
import { readdirSync, statSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = '/output';
const files = [];
(function walk(p) {
  for (const name of readdirSync(p).sort()) {
    const full = join(p, name);
    if (statSync(full).isDirectory()) walk(full);
    else if (full.endsWith('.mjs')) files.push(full);
  }
})(ROOT);

const BANNED = [
  'JSON.', 'JSON[', 'RegExp', 'require(', 'module.exports', 'exports.',
  '.match(', '.matchAll(', '.search(', 'toRegex',
];

let problems = 0;
for (const f of files) {
  const buf = readFileSync(f);
  const text = buf.toString('utf8');
  const lines = text.split('\n');
  for (let i = 0; i < buf.length; i++) {
    const b = buf[i];
    const ok = b === 0x09 || b === 0x0a || (b >= 0x20 && b <= 0x7e);
    if (!ok) {
      const upto = buf.slice(0, i).toString('utf8');
      let line = 1;
      for (const ch of upto) if (ch === '\n') line++;
      console.log('NON-ASCII BYTE 0x' + b.toString(16) + ' at ' + f + ':' + line);
      problems++;
      break;
    }
  }
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    for (const bad of BANNED) {
      if (line.includes(bad)) {
        console.log('BANNED "' + bad + '" at ' + f + ':' + (i + 1) + ': ' + line.trim());
        problems++;
      }
    }
    // a regex literal is hard to detect without parsing; flag the common shapes
    const t = line.trim();
    if (t.includes('= /') || t.includes('(/') || t.includes('.replace(/') || t.includes('.split(/')) {
      console.log('POSSIBLE REGEX at ' + f + ':' + (i + 1) + ': ' + t);
      problems++;
    }
    if (t.startsWith('import ') || t.startsWith('} from ') || t.includes(" from '")) {
      const q = t.indexOf(" from '");
      const spec = q >= 0 ? t.slice(q + 7, t.indexOf("'", q + 7)) : null;
      if (spec !== null && !spec.startsWith('./') && !spec.startsWith('../') && !spec.startsWith('node:')) {
        console.log('NON-LOCAL IMPORT "' + spec + '" at ' + f + ':' + (i + 1));
        problems++;
      }
    }
  }
}
console.log(problems === 0 ? 'lint ok (' + files.length + ' files)' : problems + ' problem(s)');
if (problems) process.exitCode = 1;

