// The Python value model.
//
// safe_load() must produce values that behave like Python objects, because
// yaml.dump() then formats them with Python semantics (int vs float, dict key
// identity, set/tuple/datetime types, insertion order, aliasing by identity).
//
// Mapping used throughout this project:
//
//   Python          JavaScript
//   ------          ----------
//   None            null
//   bool            true / false
//   int             BigInt              (typeof v === 'bigint')
//   float           Number              (typeof v === 'number')
//   str             String
//   bytes           PyBytes
//   list            Array
//   tuple           PyTuple
//   dict            PyDict              (insertion-ordered, Python key equality)
//   set             PySet
//   datetime.date   PyDate
//   datetime.datetime PyDateTime
//
// Keeping ints as BigInt is what makes `1` dump as `1` and `1.0` dump as `1.0`,
// and it preserves integers far beyond 2**53 exactly.
import { PyTypeError } from '../errors.mjs';

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export class PyDate {
  constructor(year, month, day) {
    this.year = year;
    this.month = month;
    this.day = day;
  }
}

export class PyDateTime {
  /** tzMinutes is null for a naive datetime, otherwise the UTC offset in minutes. */
  constructor(year, month, day, hour, minute, second, microsecond, tzMinutes) {
    this.year = year;
    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.tzMinutes = tzMinutes === undefined ? null : tzMinutes;
  }
}

/** Raised where Python would raise `TypeError: unhashable type: 'list'`. */
export class PyUnhashableError extends PyTypeError {
  constructor(typeName) {
    super("unhashable type: '" + typeName + "'");
    this.typeName = typeName;
  }
}

/**
 * The Python type name of a value, as `type(v).__name__` would report it
 * (datetimes use the dotted form Python's error messages use).
 */
export function pyTypeOf(v) {
  if (v === null || v === undefined) return 'none';
  const t = typeof v;
  if (t === 'boolean') return 'bool';
  if (t === 'bigint') return 'int';
  if (t === 'number') return 'float';
  if (t === 'string') return 'str';
  if (Array.isArray(v)) return 'list';
  if (v instanceof PyBytes) return 'bytes';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PyDict) return 'dict';
  if (v instanceof PySet) return 'set';
  if (v instanceof PyDateTime) return 'datetime';
  if (v instanceof PyDate) return 'date';
  return 'unknown';
}

const TYPE_DISPLAY = {
  none: 'NoneType',
  bool: 'bool',
  int: 'int',
  float: 'float',
  str: 'str',
  bytes: 'bytes',
  list: 'list',
  tuple: 'tuple',
  dict: 'dict',
  set: 'set',
  date: 'datetime.date',
  datetime: 'datetime.datetime',
  unknown: 'object',
};

export function pyTypeName(v) {
  return TYPE_DISPLAY[pyTypeOf(v)];
}

let nanCounter = 0;

/**
 * A string that stands in for Python's (hash, ==) pair: two values collide iff
 * Python considers them the same dict key. Notably `1`, `1.0` and `True` all
 * map to the same key, and NaN is never equal to itself.
 */
export function hashKey(v) {
  const t = pyTypeOf(v);
  switch (t) {
    case 'none':
      return 'N';
    case 'bool':
      return v ? 'i:1' : 'i:0';
    case 'int':
      return 'i:' + v.toString();
    case 'float': {
      if (Number.isNaN(v)) {
        nanCounter += 1;
        return 'nan:' + nanCounter; // each NaN is its own key, as in Python
      }
      if (v === Infinity) return 'f:inf';
      if (v === -Infinity) return 'f:-inf';
      if (Number.isInteger(v)) return 'i:' + BigInt(v).toString();
      return 'f:' + v.toString();
    }
    case 'str':
      return 's:' + v;
    case 'bytes': {
      let s = 'b:';
      for (const byte of v.bytes) s += byte.toString(16).padStart(2, '0');
      return s;
    }
    case 'tuple': {
      let s = 'u:' + v.items.length + ':';
      for (const item of v.items) {
        const k = hashKey(item);
        s += k.length + '|' + k;
      }
      return s;
    }
    case 'date':
      return 'D:' + v.year + '-' + v.month + '-' + v.day;
    case 'datetime':
      return (
        'T:' + v.year + '-' + v.month + '-' + v.day + ' ' + v.hour + ':' + v.minute + ':' +
        v.second + '.' + v.microsecond + ':' + (v.tzMinutes === null ? 'naive' : v.tzMinutes)
      );
    case 'list':
      throw new PyUnhashableError('list');
    case 'dict':
      throw new PyUnhashableError('dict');
    case 'set':
      throw new PyUnhashableError('set');
    default:
      throw new PyUnhashableError('object');
  }
}

/** True when Python would accept the value as a dict key. */
export function isHashable(v) {
  const t = pyTypeOf(v);
  return t !== 'list' && t !== 'dict' && t !== 'set' && t !== 'unknown';
}

/** Python `a == b` for the value kinds this project produces. */
