// The Python value model.
//
// safe_load() must produce values that behave like Python objects, because
// yaml.dump() then formats them with Python semantics (int vs float, dict key
// identity, set/tuple/datetime types, insertion order, aliasing by identity).
//
// Mapping used throughout this project:
//
//   Python          JavaScript
//   ------          ----------
//   None            null
//   bool            true / false
//   int             BigInt              (typeof v === 'bigint')
//   float           Number              (typeof v === 'number')
//   str             String
//   bytes           PyBytes
//   list            Array
//   tuple           PyTuple
//   dict            PyDict              (insertion-ordered, Python key equality)
//   set             PySet
//   datetime.date   PyDate
//   datetime.datetime PyDateTime
//
// Keeping ints as BigInt is what makes `1` dump as `1` and `1.0` dump as `1.0`,
// and it preserves integers far beyond 2**53 exactly.
import { PyTypeError } from '../errors.mjs';

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export class PyDate {
  constructor(year, month, day) {
    this.year = year;
    this.month = month;
    this.day = day;
  }
}

export class PyDateTime {
  /** tzMinutes is null for a naive datetime, otherwise the UTC offset in minutes. */
  constructor(year, month, day, hour, minute, second, microsecond, tzMinutes) {
    this.year = year;
    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.tzMinutes = tzMinutes === undefined ? null : tzMinutes;
  }
}

/** Raised where Python would raise `TypeError: unhashable type: 'list'`. */
export class PyUnhashableError extends PyTypeError {
  constructor(typeName) {
    super("unhashable type: '" + typeName + "'");
    this.typeName = typeName;
  }
}

