 * The Python type name of a value, as `type(v).__name__` would report it
 * (datetimes use the dotted form Python's error messages use).
 */
export function pyTypeOf(v) {
  if (v === null || v === undefined) return 'none';
  const t = typeof v;
  if (t === 'boolean') return 'bool';
  if (t === 'bigint') return 'int';
  if (t === 'number') return 'float';
  if (t === 'string') return 'str';
  if (Array.isArray(v)) return 'list';
  if (v instanceof PyBytes) return 'bytes';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PyDict) return 'dict';
  if (v instanceof PySet) return 'set';
  if (v instanceof PyDateTime) return 'datetime';
  if (v instanceof PyDate) return 'date';
  return 'unknown';
}

const TYPE_DISPLAY = {
  none: 'NoneType',
  bool: 'bool',
  int: 'int',
  float: 'float',
  str: 'str',
  bytes: 'bytes',
  list: 'list',
  tuple: 'tuple',
  dict: 'dict',
  set: 'set',
  date: 'datetime.date',
  datetime: 'datetime.datetime',
  unknown: 'object',
};

