// Python ordering semantics.
//
// yaml.dump() sorts mapping keys with Python's sorted(), which raises TypeError
// for values of unrelated types; PyYAML swallows that error and falls back to
// insertion order. Reproducing both halves matters for byte-identical output.
import { PyTypeError } from '../errors.mjs';
import { pyTypeOf, pyTypeName } from './values.mjs';

/** Which values may be compared with each other at all. */
function orderGroup(v) {
  const t = pyTypeOf(v);
  if (t === 'bool' || t === 'int' || t === 'float') return 'numeric';
  return t;
}

function compareCodePoints(a, b) {
  const ai = Array.from(a);
  const bi = Array.from(b);
  const n = Math.min(ai.length, bi.length);
  for (let i = 0; i < n; i++) {
    const x = ai[i].codePointAt(0);
    const y = bi[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  if (ai.length === bi.length) return 0;
  return ai.length < bi.length ? -1 : 1;
}

function compareBytes(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
  }
  if (a.length === b.length) return 0;
  return a.length < b.length ? -1 : 1;
}

function toNumericParts(v) {
  const t = pyTypeOf(v);
  if (t === 'bool') return { kind: 'int', value: v ? 1n : 0n };
  if (t === 'int') return { kind: 'int', value: v };
  return { kind: 'float', value: v };
}

function compareNumeric(a, b) {
  const pa = toNumericParts(a);
  const pb = toNumericParts(b);
  if (pa.kind === 'int' && pb.kind === 'int') {
    if (pa.value === pb.value) return 0;
    return pa.value < pb.value ? -1 : 1;
  }
  if (pa.kind === 'float' && pb.kind === 'float') {
    if (Number.isNaN(pa.value) || Number.isNaN(pb.value)) return 0;
    if (pa.value === pb.value) return 0;
    return pa.value < pb.value ? -1 : 1;
  }
  // exact int/float comparison (no precision loss for huge integers)
  const flipped = pa.kind === 'float';
  const i = flipped ? pb.value : pa.value;
  const f = flipped ? pa.value : pb.value;
  let cmp;
  if (Number.isNaN(f)) return 0;
  if (f === Infinity) cmp = -1;
  else if (f === -Infinity) cmp = 1;
  else {
    const floor = Math.floor(f);
    const fBig = BigInt(floor);
    if (i < fBig) cmp = -1;
    else if (i > fBig) cmp = 1;
    else cmp = floor === f ? 0 : -1; // i === floor(f) < f when f has a fraction
  }
  return flipped ? -cmp : cmp;
}

function unorderable(a, b) {
  return new PyTypeError(
    "'<' not supported between instances of '" + pyTypeName(a) + "' and '" + pyTypeName(b) + "'"
  );
}

function dateTuple(v) {
  return [v.year, v.month, v.day];
}

function dateTimeTuple(v) {
  return [v.year, v.month, v.day, v.hour, v.minute, v.second, v.microsecond];
}

function compareNumberLists(a, b) {
  for (let i = 0; i < Math.min(a.length, b.length); i++) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
  }
  return 0;
}

/** Python's three-way comparison; throws PyTypeError where Python would. */
export function pyCompare(a, b) {
  const ga = orderGroup(a);
  const gb = orderGroup(b);
  if (ga === 'numeric' && gb === 'numeric') return compareNumeric(a, b);
  if (ga !== gb) {
    if ((ga === 'date' && gb === 'datetime') || (ga === 'datetime' && gb === 'date')) {
      throw new PyTypeError(
        "can't compare " + pyTypeName(a) + ' to ' + pyTypeName(b)
      );
    }
    throw unorderable(a, b);
  }
  switch (ga) {
    case 'str':
      return compareCodePoints(a, b);
    case 'bytes':
      return compareBytes(a.bytes, b.bytes);
    case 'date':
      return compareNumberLists(dateTuple(a), dateTuple(b));
    case 'datetime': {
      const aAware = a.tzMinutes !== null;
      const bAware = b.tzMinutes !== null;
      if (aAware !== bAware) {
        throw new PyTypeError("can't compare offset-naive and offset-aware datetimes");
      }
      if (!aAware) return compareNumberLists(dateTimeTuple(a), dateTimeTuple(b));
