      const shift = (v) => {
        const days = daysFromCivil(v.year, v.month, v.day);
        const micros =
          BigInt(days) * 86400000000n +
          BigInt(v.hour) * 3600000000n +
          BigInt(v.minute) * 60000000n +
          BigInt(v.second) * 1000000n +
          BigInt(v.microsecond) -
          BigInt(v.tzMinutes) * 60000000n;
        return micros;
      };
      const x = shift(a);
      const y = shift(b);
      if (x === y) return 0;
      return x < y ? -1 : 1;
    }
    case 'list':
    case 'tuple': {
      const ia = ga === 'list' ? a : a.items;
      const ib = gb === 'list' ? b : b.items;
      const n = Math.min(ia.length, ib.length);
      for (let i = 0; i < n; i++) {
        const c = pyCompare(ia[i], ib[i]);
        if (c !== 0) return c;
      }
      if (ia.length === ib.length) return 0;
      return ia.length < ib.length ? -1 : 1;
    }
    default:
      // None, dict, set: not orderable, not even against themselves
      throw unorderable(a, b);
  }
}

/** Days since 1970-01-01 for a proleptic Gregorian date (Howard Hinnant's algorithm). */
export function daysFromCivil(y, m, d) {
  let year = y;
  year -= m <= 2 ? 1 : 0;
  const era = Math.floor(year / 400);
  const yoe = year - era * 400;
  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

/** True when every pair in the list can be compared without a TypeError. */
function allComparable(keys) {
  if (keys.length < 2) return true;
  const groups = keys.map(orderGroup);
  const first = groups[0];
  for (const g of groups) if (g !== first) return false;
  if (first === 'none' || first === 'dict' || first === 'set' || first === 'unknown') return false;
  if (first === 'datetime') {
    const aware = keys[0].tzMinutes !== null;
    for (const k of keys) if ((k.tzMinutes !== null) !== aware) return false;
    return true;
  }
  if (first === 'list' || first === 'tuple') {
    for (let i = 0; i < keys.length; i++) {
      for (let j = i + 1; j < keys.length; j++) {
        try {
          pyCompare(keys[i], keys[j]);
        } catch {
          return false;
        }
      }
    }
  }
  return true;
}

/**
 * sorted(mapping.items()) with PyYAML's try/except TypeError fallback:
 * returns a stably sorted copy, or the input untouched when Python's sort
 * would have raised.
 */
export function trySortEntriesByKey(entries) {
  const keys = entries.map((e) => e[0]);
  if (!allComparable(keys)) return entries;
  const indexed = entries.map((e, i) => ({ e, i }));
  try {
    indexed.sort((x, y) => {
      const c = pyCompare(x.e[0], y.e[0]);
      return c !== 0 ? c : x.i - y.i; // stable
    });
  } catch {
    return entries;
  }
  return indexed.map((x) => x.e);
}

/** sorted(list) with the same fallback, used for sets. */
export function trySortValues(values) {
  if (!allComparable(values)) return values;
  const indexed = values.map((v, i) => ({ v, i }));
  try {
    indexed.sort((x, y) => {
      const c = pyCompare(x.v, y.v);
      return c !== 0 ? c : x.i - y.i;
    });
  } catch {
    return values;
  }
  return indexed.map((x) => x.v);
}

