 * CPython uses the shortest round-tripping digit string and switches to
 * exponential notation when the decimal point position `decpt` satisfies
 * decpt <= -4 or decpt > 16; the exponent is always signed and at least two
 * digits, and fixed notation always keeps a fractional part ("1.0", not "1").
 * JavaScript's Number#toExponential() (no argument) yields the same shortest
 * digits, so only the layout rules have to be reimplemented.
 */
export function pyFloatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  const negative = value < 0 || (value === 0 && 1 / value < 0);
  const abs = negative ? -value : value;

  let digits;
  let exp10;
  if (abs === 0) {
    digits = '0';
    exp10 = 0;
  } else {
    const s = abs.toExponential(); // "d.dddde+X" with the fewest digits possible
    const eIndex = s.indexOf('e');
    const mantissa = s.slice(0, eIndex);
    exp10 = parseExponent(s.slice(eIndex + 1));
    const dot = mantissa.indexOf('.');
    digits = dot < 0 ? mantissa : mantissa.slice(0, dot) + mantissa.slice(dot + 1);
    // defensive: shortest form never has trailing zeros, but keep it canonical
    let end = digits.length;
    while (end > 1 && digits.charAt(end - 1) === '0') end -= 1;
    digits = digits.slice(0, end);
  }

  const decpt = exp10 + 1;
  let body;
  if (decpt <= -4 || decpt > 16) {
    body = digits.charAt(0) + (digits.length > 1 ? '.' + digits.slice(1) : '');
    const e = decpt - 1;
    const eAbs = (e < 0 ? -e : e).toString();
    body += 'e' + (e < 0 ? '-' : '+') + (eAbs.length < 2 ? '0' + eAbs : eAbs);
  } else if (decpt <= 0) {
    body = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    body = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    body = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
