// Scanner tokens. The `id` strings are the ones PyYAML prints in parser errors
// ("expected <block end>, but found '?'"), so they must match exactly.

export class Token {
  constructor(startMark, endMark) {
    this.startMark = startMark;
    this.endMark = endMark;
  }
  get id() {
    return this.constructor.ID;
  }
}

function simpleToken(id) {
  const cls = class extends Token {};
  cls.ID = id;
  return cls;
}

export const StreamEndToken = simpleToken('<stream end>');
export const DocumentStartToken = simpleToken('<document start>');
export const DocumentEndToken = simpleToken('<document end>');
export const BlockSequenceStartToken = simpleToken('<block sequence start>');
export const BlockMappingStartToken = simpleToken('<block mapping start>');
export const BlockEndToken = simpleToken('<block end>');
export const FlowSequenceStartToken = simpleToken('[');
export const FlowMappingStartToken = simpleToken('{');
export const FlowSequenceEndToken = simpleToken(']');
export const FlowMappingEndToken = simpleToken('}');
export const KeyToken = simpleToken('?');
export const ValueToken = simpleToken(':');
export const BlockEntryToken = simpleToken('-');
export const FlowEntryToken = simpleToken(',');

export class StreamStartToken extends Token {
  constructor(startMark, endMark, encoding = null) {
    super(startMark, endMark);
    this.encoding = encoding;
  }
}
StreamStartToken.ID = '<stream start>';

export class DirectiveToken extends Token {
  constructor(name, value, startMark, endMark) {
    super(startMark, endMark);
    this.name = name;
    this.value = value;
  }
}
DirectiveToken.ID = '<directive>';

export class AliasToken extends Token {
  constructor(value, startMark, endMark) {
    super(startMark, endMark);
    this.value = value;
  }
}
AliasToken.ID = '<alias>';

export class AnchorToken extends Token {
  constructor(value, startMark, endMark) {
    super(startMark, endMark);
    this.value = value;
  }
}
AnchorToken.ID = '<anchor>';

export class TagToken extends Token {
  /** value is a [handle, suffix] pair; handle is null for verbatim tags. */
  constructor(value, startMark, endMark) {
    super(startMark, endMark);
    this.value = value;
  }
}
TagToken.ID = '<tag>';

export class ScalarToken extends Token {
  constructor(value, plain, startMark, endMark, style = null) {
    super(startMark, endMark);
    this.value = value;
    this.plain = plain;
    this.style = style;
  }
}
ScalarToken.ID = '<scalar>';

