export class Node {
  constructor(tag, value, startMark = null, endMark = null) {
    this.tag = tag;
    this.value = value;
    this.startMark = startMark;
    this.endMark = endMark;
  }
  get id() {
    return this.constructor.ID;
  }
}

export class ScalarNode extends Node {
  constructor(tag, value, startMark = null, endMark = null, style = null) {
    super(tag, value, startMark, endMark);
    this.style = style;
  }
}
ScalarNode.ID = 'scalar';

export class CollectionNode extends Node {
  constructor(tag, value, startMark = null, endMark = null, flowStyle = null) {
    super(tag, value, startMark, endMark);
    this.flowStyle = flowStyle;
  }
}

export class SequenceNode extends CollectionNode {}
SequenceNode.ID = 'sequence';

/** value is an array of [keyNode, valueNode] pairs. */
export class MappingNode extends CollectionNode {}
MappingNode.ID = 'mapping';

