// The character reader: a code-point cursor over the input document.
//
// Working on code points (not UTF-16 units) matters: astral characters such as
// U+1F600 are a single character to YAML, and marks/columns count them as one.
import { Mark, ReaderError } from '../errors.mjs';
import { NUL, CR, LF, NEL, LS, PS, isPrintableCodePoint } from '../chars.mjs';

export class Reader {
  constructor(text) {
    this.name = '<unicode string>';
    this.checkPrintable(text);
    // Array of single-code-point strings, terminated by NUL like PyYAML's buffer.
    this.buffer = Array.from(text);
    this.buffer.push(NUL);
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
  }

  checkPrintable(text) {
    let position = 0;
    for (const ch of text) {
      const cp = ch.codePointAt(0);
      if (!isPrintableCodePoint(cp)) {
        throw new ReaderError(
          '<unicode string>',
          position,
          cp,
          'unicode',
          'special characters are not allowed'
        );
      }
      position += 1;
    }
  }

  /** The character `index` positions ahead, or NUL past the end. */
  peek(index = 0) {
    const ch = this.buffer[this.pointer + index];
    return ch === undefined ? NUL : ch;
  }

  /** The next `length` characters as a string (may be shorter at the end). */
  prefix(length = 1) {
    let out = '';
    for (let i = 0; i < length; i++) {
      const ch = this.buffer[this.pointer + i];
      if (ch === undefined) break;
      out += ch;
    }
    return out;
  }

  forward(length = 1) {
    let n = length;
    while (n > 0) {
      const ch = this.buffer[this.pointer];
      if (ch === undefined) break;
      this.pointer += 1;
      this.index += 1;
      if (
        ch === LF || ch === NEL || ch === LS || ch === PS ||
        (ch === CR && this.buffer[this.pointer] !== LF)
      ) {
        this.line += 1;
        this.column = 0;
      } else {
        this.column += 1;
      }
      n -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column, this.buffer, this.pointer);
  }
}

