// The representer: Python values -> representation graph.
//
// Mirrors PyYAML's BaseRepresenter/SafeRepresenter, including the identity-keyed
// `representedObjects` table that turns a shared object into an anchor/alias and
// the key sorting that yaml.dump(sort_keys=True) performs.
import { ScalarNode, SequenceNode, MappingNode } from '../load/nodes.mjs';
import { RepresenterError } from '../errors.mjs';
import {
  PyBytes, PyTuple, PyDict, PySet, PyDate, PyDateTime, pyTypeOf,
} from '../python/values.mjs';
import { trySortEntriesByKey } from '../python/ordering.mjs';
import {
  pyFloatRepr, pyIntRepr, dateIsoformat, datetimeIsoformat, base64EncodeBytes,
} from '../python/format.mjs';

const TAG_NULL = 'tag:yaml.org,2002:null';
const TAG_STR = 'tag:yaml.org,2002:str';
const TAG_BOOL = 'tag:yaml.org,2002:bool';
const TAG_INT = 'tag:yaml.org,2002:int';
const TAG_FLOAT = 'tag:yaml.org,2002:float';
const TAG_BINARY = 'tag:yaml.org,2002:binary';
const TAG_TIMESTAMP = 'tag:yaml.org,2002:timestamp';
const TAG_SEQ = 'tag:yaml.org,2002:seq';
const TAG_MAP = 'tag:yaml.org,2002:map';
const TAG_SET = 'tag:yaml.org,2002:set';

export class SafeRepresenter {
  /** serializer must expose serialize(node). */
  constructor(serializer, options = {}) {
    this.serializer = serializer;
    this.defaultStyle = options.defaultStyle ?? null;
    this.defaultFlowStyle = options.defaultFlowStyle ?? false;
    this.sortKeys = options.sortKeys ?? true;
    this.representedObjects = new Map(); // object identity -> node
    this.aliasKey = null; // the object currently being represented, or null
  }

  represent(data) {
    const node = this.representData(data);
    this.serializer.serialize(node);
    this.representedObjects = new Map();
    this.aliasKey = null;
  }

  /** Only containers and datetimes can be aliased; scalars never are. */
  ignoreAliases(data) {
    if (data === null) return true;
    if (data instanceof PyTuple && data.items.length === 0) return true;
    const t = pyTypeOf(data);
    return t === 'str' || t === 'bytes' || t === 'bool' || t === 'int' || t === 'float';
  }

  representData(data) {
    this.aliasKey = this.ignoreAliases(data) ? null : data;
    if (this.aliasKey !== null) {
      const seen = this.representedObjects.get(this.aliasKey);
      if (seen !== undefined) return seen;
    }
    switch (pyTypeOf(data)) {
      case 'none':
        return this.representScalar(TAG_NULL, 'null');
      case 'str':
        return this.representScalar(TAG_STR, data);
      case 'bytes':
        return this.representScalar(TAG_BINARY, base64EncodeBytes(data.bytes), '|');
      case 'bool':
        return this.representScalar(TAG_BOOL, data ? 'true' : 'false');
      case 'int':
        return this.representScalar(TAG_INT, pyIntRepr(data));
      case 'float':
        return this.representScalar(TAG_FLOAT, representFloatValue(data));
      case 'list':
        return this.representSequence(TAG_SEQ, data);
      case 'tuple':
        return this.representSequence(TAG_SEQ, data.items);
      case 'dict':
        return this.representMapping(TAG_MAP, data);
      case 'set': {
        const asDict = new PyDict();
        for (const item of data.values()) asDict.set(item, null);
        return this.representMapping(TAG_SET, asDict);
      }
      case 'date':
        return this.representScalar(TAG_TIMESTAMP, dateIsoformat(data));
      case 'datetime':
        return this.representScalar(TAG_TIMESTAMP, datetimeIsoformat(data, ' '));
      default:
        throw new RepresenterError('cannot represent an object');
    }
  }

  representScalar(tag, value, style = null) {
    const node = new ScalarNode(tag, value, null, null, style === null ? this.defaultStyle : style);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    return node;
  }

  representSequence(tag, sequence, flowStyle = null) {
    const value = [];
    const node = new SequenceNode(tag, value, null, null, flowStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    let bestStyle = true;
    for (const item of sequence) {
      const itemNode = this.representData(item);
      if (!(itemNode instanceof ScalarNode && !itemNode.style)) bestStyle = false;
      value.push(itemNode);
    }
    if (flowStyle === null) {
      node.flowStyle = this.defaultFlowStyle !== null ? this.defaultFlowStyle : bestStyle;
    }
    return node;
  }

  representMapping(tag, mapping, flowStyle = null) {
    const value = [];
    const node = new MappingNode(tag, value, null, null, flowStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    let bestStyle = true;
    let entries = mapping instanceof PyDict ? mapping.entries().slice() : mapping;
    if (mapping instanceof PyDict && this.sortKeys) entries = trySortEntriesByKey(entries);
    for (const [itemKey, itemValue] of entries) {
      const keyNode = this.representData(itemKey);
      const valueNode = this.representData(itemValue);
      if (!(keyNode instanceof ScalarNode && !keyNode.style)) bestStyle = false;
      if (!(valueNode instanceof ScalarNode && !valueNode.style)) bestStyle = false;
      value.push([keyNode, valueNode]);
    }
    if (flowStyle === null) {
      node.flowStyle = this.defaultFlowStyle !== null ? this.defaultFlowStyle : bestStyle;
    }
    return node;
  }
}

/**
 * PyYAML's represent_float: repr(data).lower(), with '.inf'/'-.inf'/'.nan' for
 * the specials and a '.0' inserted before an exponent that has no fraction, so
 * that the result still resolves back to !!float.
 */
function representFloatValue(data) {
  if (Number.isNaN(data)) return '.nan';
  if (data === Infinity) return '.inf';
  if (data === -Infinity) return '-.inf';
  let value = pyFloatRepr(data);
  if (!value.includes('.') && value.includes('e')) {
    const i = value.indexOf('e');
    value = value.slice(0, i) + '.0e' + value.slice(i + 1);
  }
  return value;
}

// Re-exported so the serializer can build the same tags without duplicating them.
export const TAGS = {
  NULL: TAG_NULL, STR: TAG_STR, BOOL: TAG_BOOL, INT: TAG_INT, FLOAT: TAG_FLOAT,
  BINARY: TAG_BINARY, TIMESTAMP: TAG_TIMESTAMP, SEQ: TAG_SEQ, MAP: TAG_MAP, SET: TAG_SET,
};

// Silence unused-import warnings for the value classes used only via pyTypeOf.
void PyBytes;
void PySet;
void PyDate;
void PyDateTime;

