// A hand-written stand-in for the exact argparse configuration used by the
// original program:
//
//     parser = argparse.ArgumentParser()
//     parser.add_argument('--a', type=str, required=True)
//
// Only the behaviours argparse actually exhibits for this configuration are
// implemented, but those are reproduced faithfully: prefix abbreviation of long
// options, '--' as an end-of-options marker, '--a=value' attached values, the
// "looks like a negative number" heuristic that lets '-5' be a value while '-x'
// is not, last-wins for a repeated option, the required-arguments check firing
// before the unrecognized-arguments check, and exit status 2 for usage errors.
import { isDigit } from '../chars.mjs';

/** Thrown to unwind out of parsing; the caller performs the actual I/O. */
export class ArgparseExit extends Error {
  constructor(code, stdout, stderr) {
    super('argparse exit ' + code);
    this.name = 'ArgparseExit';
    this.code = code;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

const HELP_OPTIONS = ['-h', '--help'];
const VALUE_OPTION = '--a';
const ALL_OPTIONS = ['-h', '--help', '--a'];

export function formatUsage(prog) {
  return 'usage: ' + prog + ' [-h] --a A\n';
}

export function formatHelp(prog) {
  return (
    formatUsage(prog) +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n'
  );
}

function usageError(prog, message) {
  return new ArgparseExit(2, '', formatUsage(prog) + prog + ': error: ' + message + '\n');
}

/** argparse's _negative_number_matcher: ^-\d+$ or ^-\d*\.\d+$ */
function looksLikeNegativeNumber(text) {
  if (text.charAt(0) !== '-') return false;
  const rest = text.slice(1);
  if (rest.length === 0) return false;
  let digitsOnly = true;
  for (const ch of rest) {
    if (!isDigit(ch)) {
      digitsOnly = false;
      break;
    }
  }
  if (digitsOnly) return true;
  const dot = rest.indexOf('.');
  if (dot < 0) return false;
  const intPart = rest.slice(0, dot);
  const fracPart = rest.slice(dot + 1);
  if (fracPart.length === 0) return false;
  for (const ch of intPart) if (!isDigit(ch)) return false;
  for (const ch of fracPart) if (!isDigit(ch)) return false;
  return true;
}

/**
 * True when argparse would treat the token as an option rather than a value.
 * Mirrors ArgumentParser._parse_optional.
 */
function looksLikeOption(text) {
  if (text.length === 0) return false;
  if (text.charAt(0) !== '-') return false;
  if (ALL_OPTIONS.includes(text)) return true;
  if (text.length === 1) return false; // a bare '-' is a value
  if (text.includes('=')) return true;
  if (looksLikeNegativeNumber(text)) return false;
  if (text.includes(' ')) return false;
  return true;
