// A hand-written stand-in for the exact argparse configuration of the original:
//
//     parser = argparse.ArgumentParser()
//     parser.add_argument('--a', type=str, required=True)
//
// Reproduced faithfully (all verified against the reference binary):
//   * `-h` / `--help` and any unambiguous abbreviation print help on stdout, exit 0,
//     and win over every other error - unless they follow a `--` separator;
//   * `--a=value` attached values, split on the first `=` only;
//   * a repeated `--a` keeps the last value;
//   * argparse's "looks like a negative number" heuristic, which lets `-5` and
//     `-.5` be values while `-x`, `-1.` and `-.inf` are options;
//   * a token containing an ASCII space is always a value;
//   * `--` ends option parsing and is itself kept among the leftover tokens;
//   * the ambiguity pre-scan fires before any consumption;
//   * error phases: ambiguous option, then per-option errors in argv order, then
//     the required-argument check, then unrecognized arguments; all exit 2.
import { isUnicodeDigit } from './unicode_digits.mjs';

/** Thrown to unwind out of parsing; the caller performs the actual I/O. */
export class ArgparseExit extends Error {
  constructor(code, stdout, stderr) {
    super('argparse exit ' + code);
    this.name = 'ArgparseExit';
    this.code = code;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

const HELP_STRINGS = ['-h', '--help'];
const VALUE_OPTION = '--a';
// Registration order, exactly as argparse's _option_string_actions is built.
const OPTION_STRINGS = ['-h', '--help', VALUE_OPTION];

export function formatUsage(prog) {
  return 'usage: ' + prog + ' [-h] --a A\n';
}

export function formatHelp(prog) {
  return (
    formatUsage(prog) + '\n' + 'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n'
  );
}

function usageError(prog, message) {
  return new ArgparseExit(2, '', formatUsage(prog) + prog + ': error: ' + message + '\n');
}

function isDigitChar(ch) {
  return isUnicodeDigit(ch.codePointAt(0));
}

/** argparse's _negative_number_matcher: ^-\d+$ or ^-\d*\.\d+$ (Unicode \d). */
function looksLikeNegativeNumber(text) {
  const chars = Array.from(text);
  if (chars.length < 2 || chars[0] !== '-') return false;
  const rest = chars.slice(1);
  let dot = -1;
  for (let i = 0; i < rest.length; i++) {
    if (rest[i] === '.') {
      if (dot >= 0) return false;
      dot = i;
    } else if (!isDigitChar(rest[i])) {
      return false;
    }
  }
  if (dot < 0) return true; // ^-\d+$
  return dot === rest.length - 1 ? false : true; // ^-\d*\.\d+$ needs digits after the dot
