 * argparse's _parse_optional: returns null when the token is a value, otherwise
 * a descriptor of the option it names (option === null for an unknown option).
 */
function classifyToken(prog, token) {
  if (token.length === 0) return null;
  if (token.charAt(0) !== '-') return null;
  if (OPTION_STRINGS.includes(token)) return { option: token, sep: null, explicitArg: null };
  if (Array.from(token).length === 1) return null; // a bare '-' is a value
  const eq = token.indexOf('=');
  if (eq >= 0) {
    const prefix = token.slice(0, eq);
    if (OPTION_STRINGS.includes(prefix)) {
      return { option: prefix, sep: '=', explicitArg: token.slice(eq + 1) };
    }
  }
  const tuples = optionTuples(prog, token);
  if (tuples.length > 1) {
    throw usageError(
      prog,
      'ambiguous option: ' + token + ' could match ' + tuples.map((t) => t.option).join(', ')
    );
  }
  if (tuples.length === 1) return tuples[0];
  if (looksLikeNegativeNumber(token)) return null;
  if (token.includes(' ')) return null;
  return { option: null, sep: null, explicitArg: null };
