function optionTuples(prog, token) {
  const out = [];
  if (token.startsWith('--')) {
    const eq = token.indexOf('=');
    const prefix = eq >= 0 ? token.slice(0, eq) : token;
    const sep = eq >= 0 ? '=' : null;
    const explicitArg = eq >= 0 ? token.slice(eq + 1) : null;
    for (const option of OPTION_STRINGS) {
      if (option.startsWith(prefix)) out.push({ option, sep, explicitArg });
    }
    return out;
  }
  const shortPrefix = token.slice(0, 2);
  if (OPTION_STRINGS.includes(shortPrefix)) {
    return [{ option: shortPrefix, sep: '', explicitArg: token.slice(2) }];
  }
  for (const option of OPTION_STRINGS) {
    if (option.startsWith(token)) out.push({ option, sep: null, explicitArg: null });
