 * Parses argv (without the interpreter/script entries).
 * Returns { a } or throws ArgparseExit.
 */
export function parseArgs(argv, options = {}) {
  const prog = options.prog ?? 'test9_executable';

  // Phase 1: classify every token up to the first '--'. Ambiguity errors here
  // pre-empt everything else, including an earlier '-h'.
  const plan = [];
  let afterSeparator = false;
  for (const token of argv) {
    if (afterSeparator) {
      plan.push({ token, pattern: 'A' });
      continue;
    }
    if (token === '--') {
      afterSeparator = true;
      plan.push({ token, pattern: '-' });
      continue;
    }
    const info = classifyToken(prog, token);
    plan.push(info === null ? { token, pattern: 'A' } : { token, pattern: 'O', info });
