  while (i < plan.length) {
    const entry = plan[i];
    if (entry.pattern !== 'O') {
      extras.push(entry.token);
      i += 1;
      continue;
    }
    const { option, sep, explicitArg } = entry.info;
    if (option === null) {
      extras.push(entry.token);
      i += 1;
      continue;
    }
    if (HELP_STRINGS.includes(option)) {
      // A tail is only re-read as more short options when it was not introduced
      // by '=' and does not itself start with a prefix character.
