// Public API: the two functions the entry point needs.
import { Reader } from './load/reader.mjs';
import { Scanner } from './load/scanner.mjs';
import { Parser } from './load/parser.mjs';
import { Composer } from './load/composer.mjs';
import { Resolver } from './load/resolver.mjs';
import { SafeConstructor } from './load/constructor.mjs';
import { Emitter } from './dump/emitter.mjs';
import { Serializer } from './dump/serializer.mjs';
import { SafeRepresenter } from './dump/representer.mjs';

/** yaml.safe_load(text) -> Python value (see lib/python/values.mjs). */
export function safeLoad(text) {
  const reader = new Reader(text);
  const scanner = new Scanner(reader);
  const parser = new Parser(scanner);
  const composer = new Composer(parser, new Resolver());
  const constructor = new SafeConstructor(composer);
  return constructor.getSingleData();
}

/** yaml.dump(data, **options) -> string. */
export function dump(data, options = {}) {
  const chunks = [];
  const emitter = new Emitter((text) => chunks.push(text), {
    canonical: options.canonical ?? false,
    indent: options.indent ?? null,
    width: options.width ?? null,
    allowUnicode: options.allowUnicode ?? false,
    lineBreak: options.lineBreak ?? null,
  });
  const serializer = new Serializer(emitter, new Resolver(), {
    encoding: null,
    explicitStart: options.explicitStart ?? null,
    explicitEnd: options.explicitEnd ?? null,
    version: options.version ?? null,
    tags: options.tags ?? null,
  });
  const representer = new SafeRepresenter(serializer, {
    defaultStyle: options.defaultStyle ?? null,
    defaultFlowStyle: options.defaultFlowStyle ?? false,
    sortKeys: options.sortKeys ?? true,
  });
  serializer.open();
  representer.represent(data);
  serializer.close();
  return chunks.join('');
}

