  start = getMark(); forward(); tokens.push(new Cls(start, getMark()))
fetchFlowSequenceEnd(): fetchFlowCollectionEnd(FlowSequenceEndToken)
fetchFlowMappingEnd():  fetchFlowCollectionEnd(FlowMappingEndToken)
fetchFlowCollectionEnd(Cls):
