  start = getMark(); forward(); tokens.push(ValueToken(start, getMark()))
fetchAlias():  savePossibleSimpleKey(); allowSimpleKey = false; tokens.push(scanAnchor(AliasToken))
fetchAnchor(): savePossibleSimpleKey(); allowSimpleKey = false; tokens.push(scanAnchor(AnchorToken))
fetchTag():    savePossibleSimpleKey(); allowSimpleKey = false; tokens.push(scanTag())
fetchLiteral(): fetchBlockScalar('|')
fetchFolded():  fetchBlockScalar('>')
fetchBlockScalar(style): allowSimpleKey = true; removePossibleSimpleKey(); tokens.push(scanBlockScalar(style))
fetchSingle(): fetchFlowScalar("'")
fetchDouble(): fetchFlowScalar('"')
fetchFlowScalar(style): savePossibleSimpleKey(); allowSimpleKey = false; tokens.push(scanFlowScalar(style))
fetchPlain(): savePossibleSimpleKey(); allowSimpleKey = false; tokens.push(scanPlain())
