scanAnchor(Cls):
  start = getMark(); indicator = peek(); name = indicator === '*' ? 'alias' : 'anchor'
  forward()
  length = 0; ch = peek(length)
  while alnum(ch) || ch === '-' || ch === '_': length += 1; ch = peek(length)
  if !length: ScannerError('while scanning an ' + name, start,
      'expected alphabetic or numeric character, but found ' + repr(ch), getMark())
  value = prefix(length); forward(length); ch = peek()
  if !(ch in WS || ch in '?:,]}%@`'): ScannerError('while scanning an ' + name, start,
      'expected alphabetic or numeric character, but found ' + repr(ch), getMark())
