    while !(ch in {NUL,' ',CR,LF,NEL,LS,PS}):
      if ch === '!': useHandle = true; break
      length += 1; ch = peek(length)
    if useHandle: handle = scanTagHandle('tag', start)
    else: handle = '!'; forward()
    suffix = scanTagUri('tag', start)
