      "expected ' ', but found " + repr(ch), getMark())
  return TagToken([handle, suffix], start, getMark())

scanTagHandle(name, start):
  ch = peek()
  if ch !== '!': ScannerError('while scanning a ' + name, start,
      "expected '!', but found " + repr(ch), getMark())
