  bytes = []; mark = getMark()
  while peek() === '%':
    forward()
    for k of [0, 1]:
      if !isHexDigit(peek(k)): ScannerError('while scanning a ' + name, start,
          'expected URI escape sequence of 2 hexadecimal numbers, but found ' + repr(peek(k)), getMark())
