  chunks.push(...breaks)
  leadingNonSpace = !(peek() === ' ' || peek() === TAB)
  length = 0; while !(peek(length) in {NUL,CR,LF,NEL,LS,PS}): length += 1
  chunks.push(prefix(length)); forward(length)
