  chomping = null; increment = null; ch = peek()
  if ch === '+' || ch === '-':
    chomping = (ch === '+'); forward(); ch = peek()
    if isDigit(ch):
      increment = Number(ch)
      if increment === 0: ScannerError('while scanning a block scalar', start,
          'expected indentation indicator in the range 1-9, but found 0', getMark())
      forward()
  else if isDigit(ch):
    increment = Number(ch)
    if increment === 0: ScannerError(... same ...)
    forward(); ch = peek()
    if ch === '+' || ch === '-': chomping = (ch === '+'); forward()
  ch = peek()
  if !(ch in {NUL,' ',CR,LF,NEL,LS,PS}): ScannerError('while scanning a block scalar', start,
      'expected chomping or indentation indicators, but found ' + repr(ch), getMark())
