scanBlockScalarIgnoredLine(start):
  while peek() === ' ': forward()
  if peek() === '#': while !(peek() in {NUL,CR,LF,NEL,LS,PS}): forward()
  if !(peek() in {NUL,CR,LF,NEL,LS,PS}): ScannerError('while scanning a block scalar', start,
