  chunks = []; maxIndent = 0; end = getMark()
  while peek() === ' ' || peek() in BREAKS:
    if peek() !== ' ': chunks.push(scanLineBreak()); end = getMark()
    else: forward(); if column > maxIndent: maxIndent = column
