scanBlockScalarBreaks(blockIndent):
  chunks = []; end = getMark()
  while column < blockIndent && peek() === ' ': forward()
  while peek() in BREAKS:
    chunks.push(scanLineBreak()); end = getMark()
    while column < blockIndent && peek() === ' ': forward()
