```

### scanFlowScalar(style)

```
ESCAPE_REPLACEMENTS (scanner direction):
  '0'->NUL 'a'->0x07 'b'->0x08 't'->TAB TAB->TAB 'n'->LF 'v'->0x0B 'f'->0x0C 'r'->CR
  'e'->0x1B ' '->' ' '"'->'"' '\\'->'\\' 'N'->NEL '_'->NBSP 'L'->LS 'P'->PS
ESCAPE_CODES: 'x'->2, 'u'->4, 'U'->8

scanFlowScalar(style):
  double = (style === '"')
  chunks = []; start = getMark(); quote = peek(); forward()
  chunks.push(...scanFlowScalarNonSpaces(double, start))
  while peek() !== quote:
    chunks.push(...scanFlowScalarSpaces(double, start))
    chunks.push(...scanFlowScalarNonSpaces(double, start))
  forward()
  return ScalarToken(chunks.join(''), false, start, getMark(), style)

scanFlowScalarNonSpaces(double, start):
  chunks = []
  loop:
    length = 0
    while !(peek(length) in {"'", '"', '\\', NUL, ' ', TAB, CR, LF, NEL, LS, PS}): length += 1
    if length: chunks.push(prefix(length)); forward(length)
    ch = peek()
    if !double && ch === "'" && peek(1) === "'": chunks.push("'"); forward(2)
    else if (double && ch === "'") || (!double && (ch === '"' || ch === '\\')):
      chunks.push(ch); forward()
    else if double && ch === '\\':
      forward(); ch = peek()
      if ch in ESCAPE_REPLACEMENTS: chunks.push(ESCAPE_REPLACEMENTS[ch]); forward()
      else if ch in ESCAPE_CODES:
        length = ESCAPE_CODES[ch]; forward()
        for k in 0..length-1:
          if !isHexDigit(peek(k)): ScannerError('while scanning a double-quoted scalar', start,
            'expected escape sequence of ' + length + ' hexdecimal numbers, but found ' + repr(peek(k)), getMark())
        chunks.push(String.fromCodePoint(parseInt(prefix(length), 16))); forward(length)
      else if ch in BREAKS: scanLineBreak(); chunks.push(...scanFlowScalarBreaks(double, start))
      else: ScannerError('while scanning a double-quoted scalar', start,
        'found unknown escape character ' + repr(ch), getMark())
    else: return chunks

scanFlowScalarSpaces(double, start):
  chunks = []; length = 0
  while peek(length) === ' ' || peek(length) === TAB: length += 1
  whitespaces = prefix(length); forward(length); ch = peek()
  if ch === NUL: ScannerError('while scanning a quoted scalar', start,
      'found unexpected end of stream', getMark())
  else if ch in BREAKS:
    lineBreak = scanLineBreak(); breaks = scanFlowScalarBreaks(double, start)
    if lineBreak !== '\n': chunks.push(lineBreak)
    else if breaks.length === 0: chunks.push(' ')
    chunks.push(...breaks)
  else: chunks.push(whitespaces)
  return chunks

scanFlowScalarBreaks(double, start):
