  loop:
    p = prefix(3)
    if (p === '---' || p === '...') && peek(3) in WS:
      ScannerError('while scanning a quoted scalar', start, 'found unexpected document separator', getMark())
    while peek() === ' ' || peek() === TAB: forward()
