    else: return chunks
```

### scanPlain

```
scanPlain():
  chunks = []; start = getMark(); end = start
  plainIndent = indent + 1
  spaces = []
  loop:
    if peek() === '#': break
    length = 0
    loop:
      ch = peek(length)
      if ch in WS
         || (ch === ':' && (peek(length+1) in WS || (flowLevel && peek(length+1) in ',[]{}')))
         || (flowLevel && ch in ',?[]{}'): break
      length += 1
    if length === 0: break
    allowSimpleKey = false
    chunks.push(...spaces); chunks.push(prefix(length)); forward(length)
    end = getMark()
    spaces = scanPlainSpaces(plainIndent, start)   // may return undefined/null
    if !spaces || spaces.length === 0 || peek() === '#' || (!flowLevel && column < plainIndent): break
  return ScalarToken(chunks.join(''), true, start, end)

scanPlainSpaces(plainIndent, start):
  chunks = []; length = 0
  while peek(length) === ' ': length += 1
  whitespaces = prefix(length); forward(length)
  ch = peek()
  if ch in BREAKS:
    lineBreak = scanLineBreak(); allowSimpleKey = true
    p = prefix(3)
    if (p === '---' || p === '...') && peek(3) in WS: return null
    breaks = []
    while peek() === ' ' || peek() in BREAKS:
      if peek() === ' ': forward()
      else:
        breaks.push(scanLineBreak())
        p = prefix(3)
        if (p === '---' || p === '...') && peek(3) in WS: return null
    if lineBreak !== '\n': chunks.push(lineBreak)
    else if breaks.length === 0: chunks.push(' ')
    chunks.push(...breaks)
  else if whitespaces: chunks.push(whitespaces)
  return chunks
```

## `repr(ch)` in error messages

Python's `repr()` of a one-character string: `'a'`, `'\t'` prints as `'\t'`,
`'\x00'` as `'\x00'`, `'\n'` as `'\n'`, a non-ASCII printable prints as itself in
single quotes. Use single quotes, and escape `\\`, `'`, and the control
characters the same way Python does (`\t`, `\n`, `\r`, `\x1b`, `\x85` -> those
exact escapes; note U+0085 prints as `'\x85'`).

