  if flowLevel: return
  while indent > column: mark = getMark(); indent = indents.pop(); tokens.push(BlockEndToken(mark, mark))

addIndent(column): if indent < column: indents.push(indent); indent = column; return true
                   return false
```

## The dispatcher

```
fetchMoreTokens():
  scanToNextToken()
  stalePossibleSimpleKeys()
  unwindIndent(column)
  ch = peek()
  if ch === NUL: return fetchStreamEnd()
  if ch === '%' && checkDirective(): return fetchDirective()
  if ch === '-' && checkDocumentStart(): return fetchDocumentStart()
  if ch === '.' && checkDocumentEnd(): return fetchDocumentEnd()
  if ch === '[': return fetchFlowSequenceStart()
  if ch === '{': return fetchFlowMappingStart()
  if ch === ']': return fetchFlowSequenceEnd()
  if ch === '}': return fetchFlowMappingEnd()
  if ch === ',': return fetchFlowEntry()
  if ch === '-' && checkBlockEntry(): return fetchBlockEntry()
  if ch === '?' && checkKey(): return fetchKey()
  if ch === ':' && checkValue(): return fetchValue()
  if ch === '*': return fetchAlias()
  if ch === '&': return fetchAnchor()
  if ch === '!': return fetchTag()
  if ch === '|' && !flowLevel: return fetchLiteral()
  if ch === '>' && !flowLevel: return fetchFolded()
  if ch === "'": return fetchSingle()
  if ch === '"': return fetchDouble()
  if checkPlain(): return fetchPlain()
  ScannerError('while scanning for the next token', null,
               'found character ' + pyRepr(ch) + ' that cannot start any token', getMark())

checkDirective():     column === 0
checkDocumentStart(): column === 0 && prefix(3) === '---' && peek(3) in WS
checkDocumentEnd():   column === 0 && prefix(3) === '...' && peek(3) in WS
checkBlockEntry():    peek(1) in WS
checkKey():           flowLevel || peek(1) in WS
checkValue():         flowLevel || peek(1) in WS
checkPlain():
  ch = peek()
  return !(ch in WS || ch in '-?:,[]{}#&*!|>\'"%@`')
      || (!(peek(1) in WS) && (ch === '-' || (!flowLevel && (ch === '?' || ch === ':'))))
```

## Fetchers

```
fetchStreamStart(): mark = getMark(); tokens.push(StreamStartToken(mark, mark, null))
fetchStreamEnd():
  unwindIndent(-1); removePossibleSimpleKey(); allowSimpleKey = false; possibleSimpleKeys.clear()
  mark = getMark(); tokens.push(StreamEndToken(mark, mark)); done = true
fetchDirective(): unwindIndent(-1); removePossibleSimpleKey(); allowSimpleKey = false
                  tokens.push(scanDirective())
fetchDocumentStart(): fetchDocumentIndicator(DocumentStartToken)
fetchDocumentEnd():   fetchDocumentIndicator(DocumentEndToken)
fetchDocumentIndicator(Cls):
  unwindIndent(-1); removePossibleSimpleKey(); allowSimpleKey = false
  start = getMark(); forward(3); tokens.push(new Cls(start, getMark()))
fetchFlowSequenceStart(): fetchFlowCollectionStart(FlowSequenceStartToken)
fetchFlowMappingStart():  fetchFlowCollectionStart(FlowMappingStartToken)
fetchFlowCollectionStart(Cls):
  savePossibleSimpleKey(); flowLevel += 1; allowSimpleKey = true
  start = getMark(); forward(); tokens.push(new Cls(start, getMark()))
fetchFlowSequenceEnd(): fetchFlowCollectionEnd(FlowSequenceEndToken)
fetchFlowMappingEnd():  fetchFlowCollectionEnd(FlowMappingEndToken)
fetchFlowCollectionEnd(Cls):
  removePossibleSimpleKey(); flowLevel -= 1; allowSimpleKey = false
  start = getMark(); forward(); tokens.push(new Cls(start, getMark()))
fetchFlowEntry():
  allowSimpleKey = true; removePossibleSimpleKey()
  start = getMark(); forward(); tokens.push(FlowEntryToken(start, getMark()))
fetchBlockEntry():
  if !flowLevel:
    if !allowSimpleKey: ScannerError(null, null, 'sequence entries are not allowed here', getMark())
    if addIndent(column): mark = getMark(); tokens.push(BlockSequenceStartToken(mark, mark))
  allowSimpleKey = true; removePossibleSimpleKey()
  start = getMark(); forward(); tokens.push(BlockEntryToken(start, getMark()))
fetchKey():
  if !flowLevel:
    if !allowSimpleKey: ScannerError(null, null, 'mapping keys are not allowed here', getMark())
    if addIndent(column): mark = getMark(); tokens.push(BlockMappingStartToken(mark, mark))
  allowSimpleKey = false; removePossibleSimpleKey()
  start = getMark(); forward(); tokens.push(KeyToken(start, getMark()))
fetchValue():
  key = possibleSimpleKeys[flowLevel]
  if key !== undefined:
    delete possibleSimpleKeys[flowLevel]
    tokens.splice(key.tokenNumber - tokensTaken, 0, KeyToken(key.mark, key.mark))
    if !flowLevel && addIndent(key.column):
      tokens.splice(key.tokenNumber - tokensTaken, 0, BlockMappingStartToken(key.mark, key.mark))
    allowSimpleKey = false
  else:
    if !flowLevel && !allowSimpleKey:
      ScannerError(null, null, 'mapping values are not allowed here', getMark())
    if !flowLevel && addIndent(column): mark = getMark(); tokens.push(BlockMappingStartToken(mark, mark))
    allowSimpleKey = !flowLevel
    removePossibleSimpleKey()
  start = getMark(); forward(); tokens.push(ValueToken(start, getMark()))
fetchAlias():  savePossibleSimpleKey(); allowSimpleKey = false; tokens.push(scanAnchor(AliasToken))
fetchAnchor(): savePossibleSimpleKey(); allowSimpleKey = false; tokens.push(scanAnchor(AnchorToken))
fetchTag():    savePossibleSimpleKey(); allowSimpleKey = false; tokens.push(scanTag())
fetchLiteral(): fetchBlockScalar('|')
fetchFolded():  fetchBlockScalar('>')
fetchBlockScalar(style): allowSimpleKey = true; removePossibleSimpleKey(); tokens.push(scanBlockScalar(style))
fetchSingle(): fetchFlowScalar("'")
fetchDouble(): fetchFlowScalar('"')
fetchFlowScalar(style): savePossibleSimpleKey(); allowSimpleKey = false; tokens.push(scanFlowScalar(style))
fetchPlain(): savePossibleSimpleKey(); allowSimpleKey = false; tokens.push(scanPlain())
```

## Scanners

```
scanToNextToken():
  if index === 0 && peek() === BOM: forward()
  found = false
  while !found:
    while peek() === ' ': forward()
    if peek() === '#': while !(peek() in {NUL, CR, LF, NEL, LS, PS}): forward()
    if scanLineBreak() !== '': if !flowLevel: allowSimpleKey = true
    else: found = true

scanLineBreak():
  ch = peek()
  if ch === CR || ch === LF || ch === NEL: forward(prefix(2) === CR+LF ? 2 : 1); return '\n'
  if ch === LS || ch === PS: forward(); return ch
  return ''

scanDirective():
  start = getMark(); forward(); name = scanDirectiveName(start); value = null
  if name === 'YAML': value = scanYamlDirectiveValue(start); end = getMark()
  else if name === 'TAG': value = scanTagDirectiveValue(start); end = getMark()
  else: end = getMark(); while !(peek() in {NUL,CR,LF,NEL,LS,PS}): forward()
  scanDirectiveIgnoredLine(start)
  return DirectiveToken(name, value, start, end)

scanDirectiveName(start):
  length = 0; ch = peek(length)
  while alnum(ch) || ch === '-' || ch === '_': length += 1; ch = peek(length)
  if !length: ScannerError('while scanning a directive', start,
      'expected alphabetic or numeric character, but found ' + repr(ch), getMark())
  value = prefix(length); forward(length); ch = peek()
  if !(ch in WS): ScannerError('while scanning a directive', start,
      'expected alphabetic or numeric character, but found ' + repr(ch), getMark())
  return value

scanYamlDirectiveValue(start):
  while peek() === ' ': forward()
  major = scanYamlDirectiveNumber(start)
  if peek() !== '.': ScannerError('while scanning a directive', start,
      "expected a digit or '.', but found " + repr(peek()), getMark())
  forward()
  minor = scanYamlDirectiveNumber(start)
  if !(peek() in WS): ScannerError('while scanning a directive', start,
      "expected a digit or ' ', but found " + repr(peek()), getMark())
  return [major, minor]

scanYamlDirectiveNumber(start):
  ch = peek()
  if !isDigit(ch): ScannerError('while scanning a directive', start,
      'expected a digit, but found ' + repr(ch), getMark())
  length = 0; while isDigit(peek(length)): length += 1
  value = Number(prefix(length)); forward(length); return value

scanTagDirectiveValue(start):
  while peek() === ' ': forward()
  handle = scanTagDirectiveHandle(start)
  while peek() === ' ': forward()
  prefixValue = scanTagDirectivePrefix(start)
  return [handle, prefixValue]

scanTagDirectiveHandle(start):
  value = scanTagHandle('directive', start)
  if peek() !== ' ': ScannerError('while scanning a directive', start,
      "expected ' ', but found " + repr(peek()), getMark())
  return value

scanTagDirectivePrefix(start):
  value = scanTagUri('directive', start)
  if !(peek() in WS): ScannerError('while scanning a directive', start,
      "expected ' ', but found " + repr(peek()), getMark())
  return value

scanDirectiveIgnoredLine(start):
  while peek() === ' ': forward()
  if peek() === '#': while !(peek() in {NUL,CR,LF,NEL,LS,PS}): forward()
  if !(peek() in {NUL,CR,LF,NEL,LS,PS}):
    ScannerError('while scanning a directive', start,
      'expected a comment or a line break, but found ' + repr(peek()), getMark())
  scanLineBreak()

scanAnchor(Cls):
  start = getMark(); indicator = peek(); name = indicator === '*' ? 'alias' : 'anchor'
  forward()
  length = 0; ch = peek(length)
  while alnum(ch) || ch === '-' || ch === '_': length += 1; ch = peek(length)
  if !length: ScannerError('while scanning an ' + name, start,
      'expected alphabetic or numeric character, but found ' + repr(ch), getMark())
  value = prefix(length); forward(length); ch = peek()
  if !(ch in WS || ch in '?:,]}%@`'): ScannerError('while scanning an ' + name, start,
      'expected alphabetic or numeric character, but found ' + repr(ch), getMark())
  return new Cls(value, start, getMark())

scanTag():
  start = getMark(); ch = peek(1)
  if ch === '<':
    handle = null; forward(2); suffix = scanTagUri('tag', start)
    if peek() !== '>': ScannerError('while parsing a tag', start,
        "expected '>', but found " + repr(peek()), getMark())
    forward()
  else if ch in WS: handle = null; suffix = '!'; forward()
  else:
    length = 1; useHandle = false
    while !(ch in {NUL,' ',CR,LF,NEL,LS,PS}):
      if ch === '!': useHandle = true; break
      length += 1; ch = peek(length)
    if useHandle: handle = scanTagHandle('tag', start)
    else: handle = '!'; forward()
    suffix = scanTagUri('tag', start)
  ch = peek()
  if !(ch in {NUL,' ',CR,LF,NEL,LS,PS}): ScannerError('while scanning a tag', start,
      "expected ' ', but found " + repr(ch), getMark())
  return TagToken([handle, suffix], start, getMark())

scanTagHandle(name, start):
  ch = peek()
  if ch !== '!': ScannerError('while scanning a ' + name, start,
      "expected '!', but found " + repr(ch), getMark())
  length = 1; ch = peek(length)
  if ch !== ' ':
    while alnum(ch) || ch === '-' || ch === '_': length += 1; ch = peek(length)
    if ch !== '!': forward(length); ScannerError('while scanning a ' + name, start,
        "expected '!', but found " + repr(ch), getMark())
    length += 1
  value = prefix(length); forward(length); return value

scanTagUri(name, start):
  chunks = []; length = 0; ch = peek(length)
  while alnum(ch) || ch in "-;/?:@&=+$,_.!~*'()[]%":
    if ch === '%': chunks.push(prefix(length)); forward(length); length = 0
                   chunks.push(scanUriEscapes(name, start))
    else: length += 1
    ch = peek(length)
  if length: chunks.push(prefix(length)); forward(length); length = 0
  if chunks.length === 0: ScannerError('while parsing a ' + name, start,
      'expected URI, but found ' + repr(ch), getMark())
  return chunks.join('')

scanUriEscapes(name, start):
  bytes = []; mark = getMark()
  while peek() === '%':
    forward()
    for k of [0, 1]:
      if !isHexDigit(peek(k)): ScannerError('while scanning a ' + name, start,
          'expected URI escape sequence of 2 hexadecimal numbers, but found ' + repr(peek(k)), getMark())
    bytes.push(parseInt(prefix(2), 16)); forward(2)
  // decode as UTF-8; on failure ScannerError('while scanning a ' + name, start, str(exc), mark)
  return utf8Decode(bytes)
```

### scanBlockScalar(style)

```
folded = (style === '>')
chunks = []; start = getMark(); forward()
[chomping, increment] = scanBlockScalarIndicators(start)   // chomping: true(+) / false(-) / null
scanBlockScalarIgnoredLine(start)
minIndent = max(indent + 1, 1)
if increment === null:
  [breaks, maxIndent, end] = scanBlockScalarIndentation()
  blockIndent = max(minIndent, maxIndent)
else:
  blockIndent = minIndent + increment - 1
  [breaks, end] = scanBlockScalarBreaks(blockIndent)
lineBreak = ''
while column === blockIndent && peek() !== NUL:
  chunks.push(...breaks)
  leadingNonSpace = !(peek() === ' ' || peek() === TAB)
  length = 0; while !(peek(length) in {NUL,CR,LF,NEL,LS,PS}): length += 1
  chunks.push(prefix(length)); forward(length)
  lineBreak = scanLineBreak()
  [breaks, end] = scanBlockScalarBreaks(blockIndent)
  if column === blockIndent && peek() !== NUL:
    if folded && lineBreak === '\n' && leadingNonSpace && !(peek() === ' ' || peek() === TAB):
      if breaks.length === 0: chunks.push(' ')
    else: chunks.push(lineBreak)
  else: break
if chomping !== false: chunks.push(lineBreak)
if chomping === true: chunks.push(...breaks)
return ScalarToken(chunks.join(''), false, start, end, style)

scanBlockScalarIndicators(start):
  chomping = null; increment = null; ch = peek()
  if ch === '+' || ch === '-':
    chomping = (ch === '+'); forward(); ch = peek()
    if isDigit(ch):
      increment = Number(ch)
      if increment === 0: ScannerError('while scanning a block scalar', start,
          'expected indentation indicator in the range 1-9, but found 0', getMark())
      forward()
  else if isDigit(ch):
    increment = Number(ch)
    if increment === 0: ScannerError(... same ...)
    forward(); ch = peek()
    if ch === '+' || ch === '-': chomping = (ch === '+'); forward()
  ch = peek()
  if !(ch in {NUL,' ',CR,LF,NEL,LS,PS}): ScannerError('while scanning a block scalar', start,
      'expected chomping or indentation indicators, but found ' + repr(ch), getMark())
  return [chomping, increment]

scanBlockScalarIgnoredLine(start):
  while peek() === ' ': forward()
  if peek() === '#': while !(peek() in {NUL,CR,LF,NEL,LS,PS}): forward()
  if !(peek() in {NUL,CR,LF,NEL,LS,PS}): ScannerError('while scanning a block scalar', start,
      'expected a comment or a line break, but found ' + repr(peek()), getMark())
  scanLineBreak()

scanBlockScalarIndentation():
  chunks = []; maxIndent = 0; end = getMark()
  while peek() === ' ' || peek() in BREAKS:
    if peek() !== ' ': chunks.push(scanLineBreak()); end = getMark()
    else: forward(); if column > maxIndent: maxIndent = column
  return [chunks, maxIndent, end]

scanBlockScalarBreaks(blockIndent):
  chunks = []; end = getMark()
  while column < blockIndent && peek() === ' ': forward()
  while peek() in BREAKS:
    chunks.push(scanLineBreak()); end = getMark()
    while column < blockIndent && peek() === ' ': forward()
  return [chunks, end]
```

### scanFlowScalar(style)

```
ESCAPE_REPLACEMENTS (scanner direction):
  '0'->NUL 'a'->0x07 'b'->0x08 't'->TAB TAB->TAB 'n'->LF 'v'->0x0B 'f'->0x0C 'r'->CR
  'e'->0x1B ' '->' ' '"'->'"' '\\'->'\\' 'N'->NEL '_'->NBSP 'L'->LS 'P'->PS
ESCAPE_CODES: 'x'->2, 'u'->4, 'U'->8

scanFlowScalar(style):
  double = (style === '"')
  chunks = []; start = getMark(); quote = peek(); forward()
  chunks.push(...scanFlowScalarNonSpaces(double, start))
  while peek() !== quote:
    chunks.push(...scanFlowScalarSpaces(double, start))
    chunks.push(...scanFlowScalarNonSpaces(double, start))
  forward()
  return ScalarToken(chunks.join(''), false, start, getMark(), style)

scanFlowScalarNonSpaces(double, start):
  chunks = []
  loop:
    length = 0
    while !(peek(length) in {"'", '"', '\\', NUL, ' ', TAB, CR, LF, NEL, LS, PS}): length += 1
    if length: chunks.push(prefix(length)); forward(length)
    ch = peek()
    if !double && ch === "'" && peek(1) === "'": chunks.push("'"); forward(2)
    else if (double && ch === "'") || (!double && (ch === '"' || ch === '\\')):
      chunks.push(ch); forward()
    else if double && ch === '\\':
      forward(); ch = peek()
      if ch in ESCAPE_REPLACEMENTS: chunks.push(ESCAPE_REPLACEMENTS[ch]); forward()
      else if ch in ESCAPE_CODES:
        length = ESCAPE_CODES[ch]; forward()
        for k in 0..length-1:
          if !isHexDigit(peek(k)): ScannerError('while scanning a double-quoted scalar', start,
            'expected escape sequence of ' + length + ' hexdecimal numbers, but found ' + repr(peek(k)), getMark())
        chunks.push(String.fromCodePoint(parseInt(prefix(length), 16))); forward(length)
      else if ch in BREAKS: scanLineBreak(); chunks.push(...scanFlowScalarBreaks(double, start))
      else: ScannerError('while scanning a double-quoted scalar', start,
        'found unknown escape character ' + repr(ch), getMark())
    else: return chunks

scanFlowScalarSpaces(double, start):
  chunks = []; length = 0
  while peek(length) === ' ' || peek(length) === TAB: length += 1
  whitespaces = prefix(length); forward(length); ch = peek()
  if ch === NUL: ScannerError('while scanning a quoted scalar', start,
      'found unexpected end of stream', getMark())
  else if ch in BREAKS:
    lineBreak = scanLineBreak(); breaks = scanFlowScalarBreaks(double, start)
    if lineBreak !== '\n': chunks.push(lineBreak)
    else if breaks.length === 0: chunks.push(' ')
    chunks.push(...breaks)
  else: chunks.push(whitespaces)
  return chunks

scanFlowScalarBreaks(double, start):
  chunks = []
  loop:
    p = prefix(3)
    if (p === '---' || p === '...') && peek(3) in WS:
      ScannerError('while scanning a quoted scalar', start, 'found unexpected document separator', getMark())
    while peek() === ' ' || peek() === TAB: forward()
    if peek() in BREAKS: chunks.push(scanLineBreak())
    else: return chunks
```

### scanPlain

```
scanPlain():
  chunks = []; start = getMark(); end = start
  plainIndent = indent + 1
  spaces = []
  loop:
    if peek() === '#': break
    length = 0
    loop:
      ch = peek(length)
      if ch in WS
         || (ch === ':' && (peek(length+1) in WS || (flowLevel && peek(length+1) in ',[]{}')))
         || (flowLevel && ch in ',?[]{}'): break
      length += 1
    if length === 0: break
    allowSimpleKey = false
    chunks.push(...spaces); chunks.push(prefix(length)); forward(length)
    end = getMark()
    spaces = scanPlainSpaces(plainIndent, start)   // may return undefined/null
    if !spaces || spaces.length === 0 || peek() === '#' || (!flowLevel && column < plainIndent): break
  return ScalarToken(chunks.join(''), true, start, end)

scanPlainSpaces(plainIndent, start):
  chunks = []; length = 0
  while peek(length) === ' ': length += 1
  whitespaces = prefix(length); forward(length)
  ch = peek()
  if ch in BREAKS:
    lineBreak = scanLineBreak(); allowSimpleKey = true
    p = prefix(3)
    if (p === '---' || p === '...') && peek(3) in WS: return null
    breaks = []
    while peek() === ' ' || peek() in BREAKS:
      if peek() === ' ': forward()
      else:
        breaks.push(scanLineBreak())
        p = prefix(3)
        if (p === '---' || p === '...') && peek(3) in WS: return null
    if lineBreak !== '\n': chunks.push(lineBreak)
    else if breaks.length === 0: chunks.push(' ')
    chunks.push(...breaks)
  else if whitespaces: chunks.push(whitespaces)
  return chunks
```

## `repr(ch)` in error messages

Python's `repr()` of a one-character string: `'a'`, `'\t'` prints as `'\t'`,
`'\x00'` as `'\x00'`, `'\n'` as `'\n'`, a non-ASCII printable prints as itself in
single quotes. Use single quotes, and escape `\\`, `'`, and the control
characters the same way Python does (`\t`, `\n`, `\r`, `\x1b`, `\x85` -> those
exact escapes; note U+0085 prints as `'\x85'`).
